'use strict';
const sharedTeachers={weize:'瑋澤老師',hexin:'和欣老師－中和高中'};
const draftPrefix='keri-shared-draft-v1:',cachePrefix='keri-shared-cache-v1:';
let cloudOwner=null,cloudSync=null,cloudEpoch=0,cloudReady=false,cloudLoading=false;
function validBook(b){return b&&b.version===2&&Array.isArray(b.workspaces)&&b.workspaces.length>0&&b.workspaces.length<=100&&new Set(b.workspaces.map(w=>w.id)).size===b.workspaces.length&&b.workspaces.every(w=>typeof w.id==='string'&&validate(w.data))&&b.workspaces.some(w=>w.id===b.active);}
async function sharedRequest(query,method='GET',body){const response=await fetch(CloudConfig.url+'/rest/v1/shared_teacher_books'+query,{method,headers:{apikey:CloudConfig.key,'Content-Type':'application/json',Prefer:'return=representation'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});if(!response.ok){const e=Error('SHARED_REQUEST_FAILED');e.code=response.status===409?'CONFLICT':String(response.status);throw e;}return response.json();}
async function fetchSharedBook(owner){const rows=await sharedRequest('?teacher_id=eq.'+owner+'&select=book,revision');const row=rows[0];if(row&&(!validBook(row.book)||!Number.isSafeInteger(row.revision)||row.revision<1))throw Error('INVALID_BOOK');return row||null;}
function applySharedBook(next){if(!validBook(next))throw Error('INVALID_BOOK');book=structuredClone(next);state=book.workspaces.find(w=>w.id===book.active).data;resetView();}
function cacheShared(){if(!cloudOwner||!cloudReady)return;try{localStorage.setItem(cachePrefix+cloudOwner,JSON.stringify({revision:cloudSync.revision,book}));}catch{}}
function syncStatus(kind){const messages={pending:'已保存在這台裝置，等待同步…',saving:'正在同步至雲端…',saved:'已同步至雲端 · '+new Date().toLocaleTimeString('zh-TW'),error:'尚未同步：資料保留在這台裝置。請確認網路與共用資料表設定，再按「立即同步」。',conflict:'其他裝置已更新課表。這份草稿已保留；請先匯出，再載入雲端版本。'};$('#syncStatus').textContent=messages[kind]||kind;if(kind==='saved')cacheShared();if(kind==='conflict')showConflict();}
function showConflict(){const area=$('#cloudActions');area.innerHTML='<button class="btn" id="draftExport">匯出此裝置草稿</button><button class="btn" id="takeRemote">載入雲端版本（保留草稿）</button>';$('#draftExport').onclick=()=>download('課日-未同步工作區.json',JSON.stringify(book,null,2),'application/json');$('#takeRemote').onclick=()=>enterTeacher(cloudOwner);}
function makeSync(owner,revision,epoch){const key=draftPrefix+owner+':'+uid();return new CloudSync({owner,revision,
 persist:d=>{if(epoch!==cloudEpoch)throw Error('STALE_TEACHER');localStorage.setItem(key,JSON.stringify(d));},
 clear:()=>localStorage.removeItem(key),status:syncStatus,
 write:async(id,rev,next)=>{if(epoch!==cloudEpoch)throw Error('STALE_TEACHER');const rows=rev?await sharedRequest('?teacher_id=eq.'+id+'&revision=eq.'+rev+'&select=revision','PATCH',{book:next}):await sharedRequest('?select=revision','POST',{teacher_id:id,book:next});return rows[0]||null;}
 });}
CalendarStore.save=function(next){if(!cloudReady||!cloudSync)throw Error('NO_TEACHER');if(!validBook(next))throw Error('INVALID_BOOK');cloudSync.stage(next);cacheShared();void cloudSync.flush();};
function teacherDrafts(owner){const result=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key.startsWith(draftPrefix+owner+':'))continue;try{const d=JSON.parse(localStorage.getItem(key));if(d.owner===owner&&validBook(d.book))result.push({key,...d});}catch{}}return result.sort((a,b)=>(b.savedAt||'').localeCompare(a.savedAt||''));}
function offerDrafts(owner){const drafts=teacherDrafts(owner).filter(d=>JSON.stringify(d.book)!==JSON.stringify(book));if(!drafts.length)return;const area=$('#cloudActions');area.innerHTML='<p>這位老師在此裝置有保留草稿；可還原為另一學期，保留目前雲端版本。</p><select id="recoverDraft" aria-label="選擇未同步草稿"></select><button class="btn" id="recoverExport">匯出選取草稿</button><button class="btn" id="recoverCopy">還原為另一學期</button>';drafts.forEach((d,i)=>$('#recoverDraft').add(new Option(d.savedAt||'未同步草稿',String(i))));$('#recoverExport').onclick=()=>download('課日-草稿工作區.json',JSON.stringify(drafts[Number($('#recoverDraft').value)].book,null,2),'application/json');$('#recoverCopy').onclick=()=>{const selected=drafts[Number($('#recoverDraft').value)];const copies=selected.book.workspaces.map(w=>({id:uid(),data:{...structuredClone(w.data),termName:(w.data.termName+'（草稿還原）').slice(0,100)}}));const next=structuredClone(book);next.workspaces.push(...copies);next.active=copies[0].id;if(!validBook(next)){toast('草稿過多或格式無效，請先匯出保存。');return;}applySharedBook(next);save();area.replaceChildren();};}
function defaultTeacherBook(owner){const w=structuredClone(owner==='hexin'?HexinPreset:TeacherPreset);return{version:2,active:w.id,workspaces:[w]};}
function localTeacherBook(owner){try{const cached=JSON.parse(localStorage.getItem(cachePrefix+owner)||'null');if(cached&&validBook(cached.book))return cached;}catch{}return null;}
function offerLegacy(owner){if(owner!=='weize')return;try{const legacy=JSON.parse(localStorage.getItem('keri-workspaces-v2')||'null');const matches=legacy?.workspaces?.filter(w=>w.data.teacher==='瑋澤老師'&&validate(w.data));if(!matches?.length)return;const area=$('#cloudActions');const box=document.createElement('div');box.innerHTML='<p>此瀏覽器有瑋澤老師的舊版資料，可另外匯入保留上課紀錄。</p><button class="btn" id="importLegacyTeacher">匯入瑋澤老師舊版紀錄為另一學期</button>';area.append(box);$('#importLegacyTeacher').onclick=()=>{const next=structuredClone(book);const copies=matches.map(w=>{const copy=structuredClone(w);correctTeacherSchedule(copy);copy.id=uid();copy.data.termName=(copy.data.termName+'（舊版匯入）').slice(0,100);return copy;});next.workspaces.push(...copies);next.active=copies[0].id;if(!validBook(next)){toast('資料格式無效，請先匯出舊版備份。');return;}applySharedBook(next);save();box.remove();};}catch{}}
async function enterTeacher(owner){if(!sharedTeachers[owner]||cloudLoading)return;cloudLoading=true;cloudReady=false;cloudSync?.close();const epoch=++cloudEpoch;document.body.classList.add('auth-locked');$('#gateMessage').textContent='正在開啟'+sharedTeachers[owner]+'的課表…';$$('dialog[open]').forEach(d=>d.close());$$('[data-teacher]').forEach(b=>b.disabled=true);$('#cloudActions').replaceChildren();
 try{let remote=null,reachable=false;try{remote=await fetchSharedBook(owner);reachable=true;}catch{}if(epoch!==cloudEpoch)return;const cached=localTeacherBook(owner);const next=remote?.book||cached?.book||defaultTeacherBook(owner);cloudOwner=owner;cloudSync=makeSync(owner,remote?.revision||(reachable?0:cached?.revision||0),epoch);applySharedBook(next);cloudReady=true;$('#accountLabel').textContent=sharedTeachers[owner]+' · 共用教學空間';document.body.classList.remove('auth-locked');
 if(remote){syncStatus('saved');offerDrafts(owner);}else{cloudSync.stage(book);cacheShared();if(reachable)void cloudSync.flush();else syncStatus('尚未連上共用資料表，目前僅保存在這台裝置。完成設定後按「立即同步」。');offerDrafts(owner);}
 if(owner==='hexin'){const imported=importHexinPreset(book);if(imported){applySharedBook(imported);save();}}
 offerLegacy(owner);if(owner==='hexin'&&state.classes.some(c=>c.id==='hx-pending'))toast('和欣老師的空間已建立，課表尚待提供。');
 }catch{$('#gateMessage').textContent='無法開啟課表，請確認瀏覽器允許儲存資料，再重試。';}finally{cloudLoading=false;$$('[data-teacher]').forEach(b=>b.disabled=false);}}
$$('[data-teacher]').forEach(b=>b.onclick=()=>enterTeacher(b.dataset.teacher));
$('#switchTeacher').onclick=()=>{cloudReady=false;cloudEpoch++;cloudSync?.close();cloudSync=null;cloudOwner=null;$$('dialog[open]').forEach(d=>d.close());document.body.classList.add('auth-locked');$('#gateMessage').textContent='請選擇老師。';};
$('#syncNow').onclick=async()=>{if(!cloudSync||!cloudReady)return;if(cloudSync.pending){await cloudSync.flush();return;}if($$('dialog[open]').length){toast('請先完成目前編輯，再載入其他裝置的更新。');return;}await enterTeacher(cloudOwner);};
window.addEventListener('online',()=>{if(cloudReady)void cloudSync?.flush();});
window.addEventListener('beforeunload',e=>{if(cloudSync?.pending){e.preventDefault();e.returnValue='';}});
// The teacher is selected at the entrance; the existing workspace control now manages terms.
$('#newWorkspace').textContent='＋ 新學期';
const originalWorkspaceOpen=$('#newWorkspace').onclick;
$('#newWorkspace').onclick=()=>{originalWorkspaceOpen();const field=$('#workspaceForm').elements.teacher;field.value=sharedTeachers[cloudOwner];field.readOnly=true;};
$('#workspaceDialog h2').textContent='新增學期';$('#workspaceDialog .help').textContent='建立這位老師的獨立學期，保留其他學期資料。';
const previousSharedRender=render;
render=function(){previousSharedRender();const unknown=state.classes.length===1&&state.classes[0].id==='hx-pending'&&state.classes[0].name==='尚未設定課表'&&!state.classes[0].slots.length;if(unknown){$('#cards').innerHTML='<p class="help">和欣老師的課表尚未提供，剩餘堂數暫無法計算。可先至「課表與段考設定」輸入課程。</p>';$('#countInfo').textContent='目前共用林口高中 115-1 全校行事曆與段考日期；各年級活動需待課表提供後核對。';}};
const restoreSingleWorkspace=$('#backupFile').onchange;
$('#backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error();const raw=JSON.parse(await file.text());if(!raw.workspaces)return restoreSingleWorkspace(e);if(!validBook(raw))throw Error();const next=structuredClone(book),copies=raw.workspaces.map(w=>({id:uid(),data:{...structuredClone(w.data),termName:(w.data.termName+'（還原）').slice(0,100)}}));next.workspaces.push(...copies);next.active=copies[0].id;if(!validBook(next))throw Error();applySharedBook(next);save();$('#settingsDialog').close();toast('已還原為另一學期，現有資料保留。');}catch{toast('備份格式無效，原資料未更動。');}finally{e.target.value='';}};
